{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Verizon Communications Inc. is a holding company that, acting through its subsidiaries, is one of the world's leading providers of communications, technology, information and streaming products and services to consumers, businesses and government entities.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0085",
          "quote": "Verizon Communications Inc. is a holding company that, acting through its subsidiaries"
        },
        {
          "chunk_id": "VZ-000073271226000007-0085",
          "quote": "one of the world’s leading providers of communications, technology, information and streaming products and services to consumers, businesses and government entities"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company has two reportable segments that it operates and manages as strategic business units: Consumer and Business.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0085",
          "quote": "We have two reportable segments that we operate and manage as strategic business units - Consumer and Business."
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue was {{m:revenue:FY-2}} in {{p:FY-2}}, {{m:revenue:FY-1}} in {{p:FY-1}}, {{m:revenue:FY0}} in {{p:FY0}}, and {{m:revenue:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The telecommunications industry is highly competitive, but Verizon believes its attractive offerings, value proposition, high-quality networks and customer base support its competitive position and ability to manage through changing market conditions.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0128",
          "quote": "The telecommunications industry is highly competitive, and we expect competition to remain intense"
        },
        {
          "chunk_id": "VZ-000073271226000007-0128",
          "quote": "our attractive offerings and value proposition as well as our high-quality networks and customer base support our competitive position"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Wholesale revenues are partly generated by a few large telecommunications companies, most of which compete directly with Verizon.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0013",
          "quote": "A portion of Wholesale revenues are generated by a few large telecommunications companies, most of which compete directly with us."
        }
      ]
    }
  ]
}

