        {
          "chunk_id": "VZ-000073271226000052-0154",
          "quote": "Net cash provided by operating activities $ 29,936 $ 28,023 $ 1,913"
        },
        {
          "chunk_id": "VZ-000073271226000052-0154",
          "quote": "Less Capital expenditures (including capitalized software) 11,926 12,263 (337)"
        }
      ]
