  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "In {{p:FY0}}, liquidity coverage was {{m:liquidity_coverage:FY0}}, but in {{p:LTM}} it declined to {{m:liquidity_coverage:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "As of June 30, 2026, the Verizon revolving credit facility had $12.0 billion of capacity, of which $11,976 million was unused.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000046-0144",
          "quote": "Verizon revolving credit facility(1)\n2028 $ 12,000 $ 11,976 $ —"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The revolving credit facility does not require compliance with financial covenants or maintenance of specified credit ratings and permits borrowing even if the business has incurred a material adverse change.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000052-0048",
          "quote": "does not require us to comply with financial covenants or maintain specified credit ratings, and it permits us to borrow even if our business has incurred a material adverse change"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "In September 2026, the company amended its $12.0 billion revolving credit facility and extended its maturity to 2030.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000052-0048",
          "quote": "In September 2026, we amended our $12.0 billion revolving credit facility and extended its maturity to 2030."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "As of September 30, 2026, the company had no commercial paper outstanding.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000052-0038",
          "quote": "As of September 30, 2026, we had no commercial paper outstanding."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Management states that sources of funds, primarily from operations and, to the extent necessary, external financing arrangements, are sufficient to meet ongoing operating and investing requirements over the next 12 months and beyond.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000046-0139",
          "quote": "Our sources of funds, primarily from operations and, to the extent necessary, from external financing arrangements, are sufficient to meet ongoing operating and investing requirements over the next 12 months and beyond."
        }
      ]
    }
  ]
}

