{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Verizon's high debt level and debt service obligations could require it to dedicate significant operating cash flow to principal and interest payments, reducing funds available for working capital, capital expenditures and dividends.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0063",
          "quote": "requiring us to dedicate significant cash flow from operations to the payment of principal, interest and other amounts payable on our debt"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Its substantial indebtedness could make future financing or refinancing for working capital, capital expenditures, debt service requirements or acquisitions more difficult or expensive.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0063",
          "quote": "making it more difficult or expensive for us to obtain any necessary future financing for working capital, capital expenditures, debt service requirements, debt refinancing, acquisitions or other purposes"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Adverse financial-market conditions or higher interest rates could raise Verizon's borrowing costs, require collateral, and make it more difficult to obtain financing or refinance existing debt.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0064",
          "quote": "make it more difficult for us to obtain financing for our operations or refinance existing indebtedness"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "An economic downturn could increase customer nonpayment and reduce demand, weakening operating cash flow available for debt repayment.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0044",
          "quote": "Adverse economic conditions may lead to an increased number of our consumer and business customers that are unable to continue paying their bills for our services."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Aggressive competitor pricing and promotions could pressure Verizon's margins and reduce cash generation needed to service debt.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0040",
          "quote": "Our competitors commonly offer aggressive pricing, promotions, premium content options and other incentives – in some cases specifically targeting our customers and putting pressure on our pricing and margins."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Further regulation of broadband, wireless and other activities could significantly increase Verizon's costs or restrict its ability to compete, limiting returns on past and future network investments.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0059",
          "quote": "could result in significant increases in costs for us or restrict our ability to compete in the marketplace"
        }
      ]
    }
  ]
